test('invoiceTotals with real invoice and discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Total = 5 * 8500;
  const line2Total = 1 * 120000;
  const line1Discount = roundCents(line1Total * 0.1);
  const line2Discount = roundCents(line2Total * 0.05);
  // Both have 21% VAT on amount after discount
  const line1Amount = line1Total - line1Discount;
  const line2Amount = line2Total - line2Discount;
  const line1VAT = roundCents(line1Amount * 0.21);
  const line2VAT = roundCents(line2Amount * 0.21);
  const expectedVAT = line1VAT + line2VAT;
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, line1Discount + line2Discount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

