test('addLine applies tier discount if discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.value.lines[1].discountPercent, 5); // gold tier discount
});

test('addLine rejects invalid discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    addLine(r.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 150 }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('addLine updates discountPercent when adding to existing SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const result = addLine(r.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 20);
});

test('invoiceTotals returns discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('discount' in totals);
  assert.ok('vat' in totals);
});

test('invoiceTotals calculates discount correctly for single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 10 * 8500;
  const expectedDiscount = roundCents(subtotal * 0.1);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, subtotal - expectedDiscount);
});

test('invoiceTotals calculates discount for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 0 },
      { qty: 1, unitPrice: 120000, discountPercent: 5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 5 * 8500;
  const line2Total = 1 * 120000;
  const line1Discount = roundCents(line1Total * 0.1);
  const line2Discount = roundCents(line2Total * 0.05);
  const expectedDiscount = line1Discount + line2Discount;
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, totals.subtotal - expectedDiscount);
});

test('invoiceTotals with 0% discount equals subtotal', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals with 100% discount brings total to 0', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 100, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const expectedDiscount = 10 * 8500;
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals clamps total at 0 (never negative)', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 100, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total >= 0, true);
});

test('invoiceTotals handles decimal discount percents', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 12.5, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 42500;
  const expectedDiscount = roundCents(42500 * 0.125);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, 0);
});

test('invoiceTotals with real invoice and discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Total = 5 * 8500;
  const line2Total = 1 * 120000;
  const line1Discount = roundCents(line1Total * 0.1);
  const line2Discount = roundCents(line2Total * 0.05);
  // Both have 21% VAT on amount after discount
  const line1Amount = line1Total - line1Discount;
  const line2Amount = line2Total - line2Discount;
  const line1VAT = roundCents(line1Amount * 0.21);
  const line2VAT = roundCents(line2Amount * 0.21);
  const expectedVAT = line1VAT + line2VAT;
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, line1Discount + line2Discount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals preserves discount field when no discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 0 },
      { qty: 1, unitPrice: 120000, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
});

test('addLine preserves discountPercent when increasing qty without new discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 15 }],
  });
  const result = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.value.lines[0].discountPercent, 15);
});

test('createInvoice with multiple lines and mixed discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 25 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
  assert.equal(r.value.lines[1].discountPercent, 5); // C-001 is gold tier: 5% discount
  assert.equal(r.value.lines[2].discountPercent, 25);
});

test('TIER_DISCOUNTS exports tier discount mapping', () => {
  assert.equal(TIER_DISCOUNTS.gold, 5);
  assert.equal(TIER_DISCOUNTS.silver, 2.5);
  assert.equal(TIER_DISCOUNTS.standard, 0);
});

test('createInvoice applies gold tier discount to lines without discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001', // Northwind Studio, gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5); // gold tier discount
});

test('createInvoice applies silver tier discount to lines without discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5); // silver tier discount
});

test('createInvoice applies standard tier discount to lines without discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0); // standard tier discount
});

test('createInvoice explicit discountPercent overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10); // explicit discount wins
});

test('createInvoice explicit 0% discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0); // explicit 0 wins over tier discount
});

test('createInvoice with mixed explicit and tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10); // explicit
  assert.equal(r.value.lines[1].discountPercent, 2.5); // silver tier
  assert.equal(r.value.lines[2].discountPercent, 0); // explicit 0
});

test('addLine applies tier discount to new line without discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 5); // gold tier discount applied
});

test('addLine explicit discountPercent overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15); // explicit overrides
});

test('addLine explicit 0% discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 0); // explicit 0 overrides tier
});

test('addLine preserves tier discount when increasing qty without new discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 5); // tier discount preserved
});

test('invoiceTotals reflects tier discounts correctly', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 10 * 8500; // 85000
  const expectedDiscount = roundCents(subtotal * 0.05); // 4250
  // DES-HOUR has 21% VAT
  const lineAmount = subtotal - expectedDiscount;
  const expectedVAT = roundCents(lineAmount * 0.21);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, subtotal - expectedDiscount + expectedVAT);
});

test('invoiceTotals with different tier discounts', () => {
  // Gold customer with 5% tier discount
  const gold = createInvoice({
    customerId: 'C-001', // gold
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  // Silver customer with 2.5% tier discount
  const silver = createInvoice({
    customerId: 'C-003', // silver
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const goldTotals = invoiceTotals(gold.value);
  const silverTotals = invoiceTotals(silver.value);

  assert.equal(goldTotals.subtotal, silverTotals.subtotal);
  assert.equal(goldTotals.discount, roundCents(85000 * 0.05));
  assert.equal(silverTotals.discount, roundCents(85000 * 0.025));
  assert.ok(goldTotals.total < silverTotals.total); // gold customer pays less due to higher discount
});

