    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10); // explicit discount wins
});

test('createInvoice explicit 0% discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0); // explicit 0 wins over tier discount
});

test('createInvoice with mixed explicit and tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10); // explicit
  assert.equal(r.value.lines[1].discountPercent, 2.5); // silver tier
  assert.equal(r.value.lines[2].discountPercent, 0); // explicit 0
});

test('addLine applies tier discount to new line without discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 5); // gold tier discount applied
});

test('addLine explicit discountPercent overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15); // explicit overrides
});

test('addLine explicit 0% discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 0); // explicit 0 overrides tier
});

test('addLine preserves tier discount when increasing qty without new discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 5); // tier discount preserved
});

test('invoiceTotals reflects tier discounts correctly', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 10 * 8500; // 85000
  const expectedDiscount = roundCents(subtotal * 0.05); // 4250
  // DES-HOUR has 21% VAT
  const lineAmount = subtotal - expectedDiscount;
  const expectedVAT = roundCents(lineAmount * 0.21);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, subtotal - expectedDiscount + expectedVAT);
});

test('invoiceTotals with different tier discounts', () => {
  // Gold customer with 5% tier discount
  const gold = createInvoice({
    customerId: 'C-001', // gold
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  // Silver customer with 2.5% tier discount
  const silver = createInvoice({
    customerId: 'C-003', // silver
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const goldTotals = invoiceTotals(gold.value);
  const silverTotals = invoiceTotals(silver.value);

  assert.equal(goldTotals.subtotal, silverTotals.subtotal);
  assert.equal(goldTotals.discount, roundCents(85000 * 0.05));
  assert.equal(silverTotals.discount, roundCents(85000 * 0.025));
  assert.ok(goldTotals.total < silverTotals.total); // gold customer pays less due to higher discount
});

test('invoiceTotals includes vat field', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const totals = invoiceTotals(r.value);
  assert.ok('vat' in totals);
  assert.equal(typeof totals.vat, 'number');
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 85000;
  const lineDiscount = roundCents(85000 * 0.1);
  const lineAmount = lineSubtotal - lineDiscount;
  const expectedVAT = roundCents(lineAmount * 0.21);
  assert.equal(totals.vat, expectedVAT);
});

test('invoiceTotals with 0% VAT rate (exempt)', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 60000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals with 9% VAT rate', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 }],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 100 * 37;
  const expectedVAT = roundCents(lineAmount * 0.09);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with 21% VAT rate', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 85000;
  const expectedVAT = roundCents(lineAmount * 0.21);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with mixed VAT rates on multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }, // Design work
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },   // Print
      { qty: 1, unitPrice: 60000, discountPercent: 0, vatRate: 0 },  // Workshop
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1VAT = roundCents(85000 * 0.21);
  const line2VAT = roundCents(3700 * 0.09);
  const line3VAT = roundCents(60000 * 0);
  const expectedVAT = line1VAT + line2VAT + line3VAT;
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals VAT calculation is per line, rounded individually', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 150, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1VAT = roundCents(300 * 0.21);
  const line2VAT = roundCents(300 * 0.21);
  const expectedVAT = line1VAT + line2VAT;
  assert.equal(totals.vat, expectedVAT);
});

test('invoiceTotals with VAT and discount together', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount), DES-HOUR has 21% VAT
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 85000;
  const discount = roundCents(85000 * 0.05);
  const lineAmount = subtotal - discount;
  const vat = roundCents(lineAmount * 0.21);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals total = subtotal - discount + vat', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expectedTotal = totals.subtotal - totals.discount + totals.vat;
  assert.equal(totals.total, expectedTotal);
});

test('renderInvoiceText shows VAT line when VAT > 0', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.includes('VAT:'));
});

test('renderInvoiceText shows subtotal and discount when discount > 0', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
});

test('renderInvoiceText formats VAT amount correctly', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const text = renderInvoiceText(r.value);
  const totals = invoiceTotals(r.value);
  const vatFormatted = formatEuros(totals.vat);
  assert.ok(text.includes(`VAT: ${vatFormatted}`));
});

